<?php declare(strict_types=1);namespace NpmGateway\Services;use NpmGateway\Exceptions\Domain\InvalidRmAuditException;
final class RmAuditValidator{public function __construct(private readonly RmAuditRichTextSanitizer$s){}public function creation(array$p):array{$tenant=trim((string)($p['tenant_name']??''));$unit=trim((string)($p['unit_identifier']??''));$property=trim((string)($p['property_public_id']??''));$raw=(string)($p['audit_findings_html']??'');$e=[];if(!preg_match('/^[0-9A-HJKMNP-TV-Z]{26}$/D',$property))$e['property_public_id']='Select a valid property.';if($tenant===''||mb_strlen($tenant)>200)$e['tenant_name']='Tenant Name is required and must not exceed 200 characters.';if($unit===''||mb_strlen($unit)>100)$e['unit_identifier']='Unit # is required and must not exceed 100 characters.';try{$rich=$this->s->sanitize($raw);}catch(\InvalidArgumentException$z){$e['audit_findings_html']=$z->getMessage();$rich=['html'=>'','text'=>''];}if($e)throw new InvalidRmAuditException($e,$p);return compact('property','tenant','unit')+['findings_html'=>$rich['html'],'findings_text'=>$rich['text']];}public function returning(array$p):string{$v=trim((string)($p['return_comments']??''));if(mb_strlen($v)<10||mb_strlen($v)>2000)throw new InvalidRmAuditException(['return_comments'=>'Return Comments must be between 10 and 2000 characters.'],$p);return$v;}}
